/* Nodo: "Code - Leer petición"  (los cinco workflows de API)

   Saca del cuerpo lo mínimo y nada más. No decide nada: quién es y qué
   puede hacer lo resuelve tes/validar-token en el nodo siguiente.

   La IP se toma de las cabeceras para la bitácora. Es informativa: la
   manda el cliente y se puede mentir, por eso NO se usa para ninguna
   decisión, solo se guarda. */

let salida;
try {
  const w = $input.first().json || {};
  const b = w.body || {};
  const h = w.headers || {};
  const ip = String(h['x-forwarded-for'] || h['x-real-ip'] || '').split(',')[0].trim();

  salida = {
    token: String(b.token || ''),
    accion: String(b.accion || ''),
    datos: (b.datos && typeof b.datos === 'object') ? b.datos : {},
    ip: ip
  };
} catch (e) {
  salida = { token: '', accion: '', datos: {}, ip: '' };
}
return [{ json: salida }];

/* Nodo: "Code - Armar consulta"  (workflow tes/tesoreria)

   Recaudación, personas, gastos y tickets. Mismo contrato que
   tes/presupuestos: catálogo cerrado, SQL literal, valores por $n,
   permiso en el WHERE y bitácora en la misma sentencia.

   Quién es TESORERA de un evento, que es de quien depende casi todo
   aquí: la tesorera general siempre; y en un evento de salón, la
   representante de ESE grupo — la que lo confirmó. Es quien captura sus
   gastos, su recaudación y sus tickets. */

const s = $input.first().json || {};
const pet = $('Code - Leer petición').first().json || {};
const d = pet.datos || {};

const no = (err) => [{ json: { ok: false, error: err, sql: 'SELECT 0 AS afectadas WHERE false', params: [] } }];
if (!s.ok) return no(s.error || 'NO_AUTORIZADO');

// Sigue solo quien está en la lista. Escrito así y no como
// `if (s.rol === 'mama') rechaza` para que un rol nuevo —o un rol
// ausente— quede FUERA por omisión, no dentro.
if (!(s.rol === 'admin' || s.rol === 'rep')) return no('ROL_SIN_PERMISO');

/* Los permisos se EXIGEN, nunca se descartan.
 *
 * La forma `if (x && x.y !== true) rechaza` no corre cuando x falta: un
 * `permisos` vacío pasaba de largo. Es la misma forma del CHECK que
 * devolvía NULL y dejaba pasar justo el caso que existía para atrapar.
 * Aquí se escribe al revés: SIGUE solo si el permiso vale exactamente
 * true; cualquier otra cosa —ausente, nulo, la cadena "true"— rechaza. */
const tienePermiso = (llave) => !!(s.permisos && s.permisos[llave] === true);


/* Se escribe contra el evento, así que el predicado vive en una
   subconsulta sobre eventos. 'e' es el alias del evento. */
const ES_TESORERA = `(
  $2::text = 'admin' OR
  (e.tipo = 'salon' AND $2::text = 'rep' AND e.grupo_id = $3::bigint)
)`;

const EVENTO_MIO = `EXISTS (
  SELECT 1 FROM eventos e
    JOIN presupuestos pp ON pp.id = e.presupuesto_id
   WHERE e.id = $6::bigint AND pp.ciclo_id = $5::bigint AND ${ES_TESORERA}
)`;

const LOG = (accion, tabla) => `
  , log AS (
      SELECT bitacora_escribir($1::bigint, '${accion}', '${tabla}', u.id,
                               (SELECT j FROM antes), u.j, $4::text) AS bid
        FROM upd u
    )`;
const CIERRE = `SELECT (SELECT count(*) FROM upd) AS afectadas,
                       (SELECT max(id) FROM upd)  AS id,
                       (SELECT count(*) FROM log) AS logs`;

const base = [s.persona_id, s.rol, s.grupo_id, pet.ip || null, s.ciclo_id];
let sql, params;

switch (pet.accion) {

  /* Recaudación y personas se guardan con UPSERT: la fila de
     evento_grupo puede no existir todavía (grupo creado a media
     operación, o evento sin capturar). evento_grupo no tiene columna
     'id' propia, así que la bitácora apunta al evento. */
  case 'recaudacion':
  case 'personas': {
    const esRec = pet.accion === 'recaudacion';
    sql = `
      WITH antes AS (
        SELECT to_jsonb(eg.*) AS j FROM evento_grupo eg
         WHERE eg.evento_id = $6::bigint AND eg.grupo_id = $7::bigint
      )
      , upd AS (
          INSERT INTO evento_grupo (evento_id, grupo_id, recaudado, adultos, ninos, ninas)
          SELECT $6::bigint, $7::bigint,
                 COALESCE($8::numeric, 0), COALESCE($9::int, 0),
                 COALESCE($10::int, 0), COALESCE($11::int, 0)
           WHERE ${EVENTO_MIO}
             AND EXISTS (SELECT 1 FROM grupos g WHERE g.id = $7::bigint AND g.ciclo_id = $5::bigint)
          ON CONFLICT (evento_id, grupo_id) DO UPDATE SET
            recaudado = COALESCE($8::numeric, evento_grupo.recaudado),
            adultos   = COALESCE($9::int,     evento_grupo.adultos),
            ninos     = COALESCE($10::int,    evento_grupo.ninos),
            ninas     = COALESCE($11::int,    evento_grupo.ninas),
            actualizado_en = now()
          RETURNING evento_id AS id, to_jsonb(evento_grupo.*) AS j
        )${LOG(esRec ? 'recaudacion' : 'personas', 'evento_grupo')}
      ${CIERRE}`;
    params = base.concat([
      d.evento_id, d.grupo_id,
      esRec ? num(d.recaudado) : null,
      esRec ? null : num(d.adultos),
      esRec ? null : num(d.ninos),
      esRec ? null : num(d.ninas)
    ]);
    break;
  }

  case 'gasto_crear':
    sql = `
      WITH antes AS (SELECT NULL::jsonb AS j)
      , upd AS (
          INSERT INTO gastos (evento_id, fecha_pago, descripcion, proveedor, monto)
          SELECT $6::bigint, $7::date, $8::text, COALESCE($9::text, ''), $10::numeric
           WHERE ${EVENTO_MIO} AND $10::numeric > 0 AND btrim($8::text) <> ''
          RETURNING id, to_jsonb(gastos.*) AS j
        )${LOG('gasto_crear', 'gastos')}
      ${CIERRE}`;
    params = base.concat([d.evento_id, d.fecha || null, String(d.descripcion || ''),
                          String(d.proveedor || ''), num(d.monto)]);
    break;

  case 'gasto_eliminar':
    sql = `
      WITH antes AS (SELECT to_jsonb(g.*) AS j FROM gastos g WHERE g.id = $7::bigint)
      , upd AS (
          DELETE FROM gastos g
           WHERE g.id = $7::bigint AND g.evento_id = $6::bigint AND ${EVENTO_MIO}
          RETURNING g.id, to_jsonb(g.*) AS j
        )${LOG('gasto_eliminar', 'gastos')}
      ${CIERRE}`;
    params = base.concat([d.evento_id, d.gasto_id]);
    break;

  /* Guarda la LLAVE del ticket. La foto ya subió al bucket directo
     desde el celular; aquí solo queda el apuntador. Con llave NULL se
     quita el ticket (y los cuatro campos se van juntos, que es lo que
     exige gastos_ticket_ok). */
  case 'ticket_fijar':
    if (!tienePermiso('tickets')) return no('SIN_PERMISO_TICKETS');
    sql = `
      WITH antes AS (SELECT to_jsonb(g.*) AS j FROM gastos g WHERE g.id = $7::bigint)
      , upd AS (
          UPDATE gastos g SET
            ticket_key    = $8::text,
            ticket_nombre = CASE WHEN $8::text IS NULL THEN NULL ELSE COALESCE($9::text, 'ticket') END,
            ticket_por    = CASE WHEN $8::text IS NULL THEN NULL ELSE $10::text END,
            ticket_en     = CASE WHEN $8::text IS NULL THEN NULL ELSE now() END
          WHERE g.id = $7::bigint AND g.evento_id = $6::bigint AND ${EVENTO_MIO}
          RETURNING g.id, to_jsonb(g.*) AS j
        )${LOG('ticket', 'gastos')}
      ${CIERRE}`;
    params = base.concat([d.evento_id, d.gasto_id, d.ticket_key || null,
                          d.nombre || null, s.nombre]);
    break;

  /* Las dos de URL firmada NO escriben. Lo único que hacen en la base
     es comprobar el permiso y traer la llave; la firma la calcula el
     nodo siguiente. Van por aquí y no por un atajo justamente para que
     el permiso se resuelva en el mismo WHERE que todo lo demás. */
  case 'ticket_subir_url':
  case 'ticket_ver_url': {
    const subir = pet.accion === 'ticket_subir_url';
    if (subir && !tienePermiso('tickets')) return no('SIN_PERMISO_TICKETS');
    sql = `
      SELECT g.id AS gasto_id, g.ticket_key,
             -- De config_app, NO de config: app_rw no alcanza el
             -- secreto del JWT ni por accidente.
             (SELECT valor FROM config_app WHERE clave = 's3_endpoint') AS s3_endpoint,
             (SELECT valor FROM config_app WHERE clave = 's3_region')   AS s3_region,
             (SELECT valor FROM config_app WHERE clave = 's3_bucket')   AS s3_bucket,
             (SELECT valor FROM config_app WHERE clave = 's3_key_id')   AS s3_key_id,
             (SELECT valor FROM config_app WHERE clave = 's3_secret')   AS s3_secret,
             (SELECT valor FROM config_app WHERE clave = 's3_estilo')   AS s3_estilo
        FROM gastos g
       WHERE g.id = $7::bigint AND g.evento_id = $6::bigint AND ${EVENTO_MIO}`;
    params = base.concat([d.evento_id, d.gasto_id]);
    return [{ json: { ok: true, sql: sql, params: params, firmar: subir ? 'PUT' : 'GET',
                      nombre_archivo: String(d.nombre || '') } }];
  }

  /* Borrar un evento es de la tesorera general y nada más. Se lleva sus
     gastos y su recaudación por ON DELETE CASCADE; el presupuesto se
     queda, como dice el aviso de la pantalla. */
  case 'evento_eliminar':
    if (s.rol !== 'admin') return no('SOLO_ADMIN');
    sql = `
      WITH antes AS (SELECT to_jsonb(e.*) AS j FROM eventos e WHERE e.id = $6::bigint)
      , upd AS (
          DELETE FROM eventos e
           USING presupuestos pp
           WHERE e.id = $6::bigint AND pp.id = e.presupuesto_id AND pp.ciclo_id = $5::bigint
          RETURNING e.id, to_jsonb(e.*) AS j
        )${LOG('evento_eliminar', 'eventos')}
      ${CIERRE}`;
    params = base.concat([d.evento_id]);
    break;

  default:
    return no('ACCION_DESCONOCIDA');
}

function num(v) { return v === undefined || v === null || v === '' ? null : Number(v); }

return [{ json: { ok: true, sql: sql, params: params } }];

/* Nodo: "Code - Firmar URL y responder"  (workflow tes/tesoreria)

   Hace las dos cosas porque es el ÚLTIMO nodo antes de responder: para
   las acciones normales responde como los otros workflows, y para las
   dos de ticket calcula además la URL firmada.

   Calcula la URL firmada del bucket. Firmar es puro HMAC: no hay red de
   por medio, así que cabe en un nodo Code aunque el sandbox no tenga
   internet. La FOTO nunca pasa por n8n ni por la base — n8n entrega la
   URL y el celular sube (o baja) directo contra el bucket.

   ⚠️ try/catch total: la entrada trae las llaves del bucket. Si el nodo
   lanzara, n8n las guardaría en el payload de error. Y la salida es un
   objeto NUEVO: las llaves no viajan aguas abajo. */

/* =====================================================================
   lib-cripto — SHA-256, HMAC, PBKDF2, base64url y JWT, en JS PURO.

   Por qué a mano: el sandbox de los nodos Code de n8n no expone
   `require`, ni `node:crypto`, ni `process`. No hay de dónde sacar una
   librería. Tampoco se asume `Buffer` ni `TextEncoder`: todo lo que
   sigue usa nada más Uint8Array, DataView, Math y JSON.

   Este archivo NO se edita en n8n. Se edita aquí y se reconstruye con
   n8n/build.py, que lo inyecta en los workflows que lo necesitan.
   ===================================================================== */

const K256 = [
  0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];

function rotr(x, n) { return ((x >>> n) | (x << (32 - n))) >>> 0; }

function sha256(msg) {
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
             0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = msg.length;
  const padLen = (((l + 9) + 63) & ~63);
  const m = new Uint8Array(padLen);
  m.set(msg);
  m[l] = 0x80;
  const dv = new DataView(m.buffer);
  // Longitud en BITS, 64 bits big-endian. Se parte en dos palabras de 32
  // porque l*8 se sale del entero seguro de JS mucho antes que el campo.
  dv.setUint32(padLen - 8, Math.floor(l / 536870912));
  dv.setUint32(padLen - 4, (l << 3) >>> 0);

  const w = new Uint32Array(64);
  for (let i = 0; i < padLen; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = dv.getUint32(i + t * 4);
    for (let t = 16; t < 64; t++) {
      const x = w[t - 15], y = w[t - 2];
      const s0 = rotr(x, 7) ^ rotr(x, 18) ^ (x >>> 3);
      const s1 = rotr(y, 17) ^ rotr(y, 19) ^ (y >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K256[t] + w[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0;
      d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0;
    H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = new Uint8Array(32);
  const odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i]);
  return out;
}

function concatBytes(a, b) {
  const r = new Uint8Array(a.length + b.length);
  r.set(a); r.set(b, a.length);
  return r;
}

function hmacSha256(key, msg) {
  const B = 64;
  let k = key.length > B ? sha256(key) : key;
  const kp = new Uint8Array(B); kp.set(k);
  const ipad = new Uint8Array(B), opad = new Uint8Array(B);
  for (let i = 0; i < B; i++) { ipad[i] = kp[i] ^ 0x36; opad[i] = kp[i] ^ 0x5c; }
  return sha256(concatBytes(opad, sha256(concatBytes(ipad, msg))));
}

/* PBKDF2-HMAC-SHA256 con salida de 32 bytes (un solo bloque). */
function pbkdf2Sha256(pass, salt, iters) {
  const blk = concatBytes(salt, new Uint8Array([0, 0, 0, 1]));
  let u = hmacSha256(pass, blk);
  const out = new Uint8Array(u);
  for (let i = 1; i < iters; i++) {
    u = hmacSha256(pass, u);
    for (let j = 0; j < 32; j++) out[j] ^= u[j];
  }
  return out;
}

/* --- codificaciones ------------------------------------------------ */

function utf8Bytes(str) {
  const s = String(str);
  const out = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c >= 0xD800 && c <= 0xDBFF && i + 1 < s.length) {
      const c2 = s.charCodeAt(i + 1);
      if (c2 >= 0xDC00 && c2 <= 0xDFFF) { c = 0x10000 + ((c - 0xD800) << 10) + (c2 - 0xDC00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xC0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xE0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xF0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return new Uint8Array(out);
}

function utf8Str(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length;) {
    const b = bytes[i];
    let c, n;
    if (b < 0x80) { c = b; n = 1; }
    else if ((b & 0xE0) === 0xC0) { c = b & 31; n = 2; }
    else if ((b & 0xF0) === 0xE0) { c = b & 15; n = 3; }
    else { c = b & 7; n = 4; }
    for (let j = 1; j < n; j++) c = (c << 6) | (bytes[i + j] & 63);
    if (c > 0xFFFF) {
      c -= 0x10000;
      s += String.fromCharCode(0xD800 + (c >> 10), 0xDC00 + (c & 1023));
    } else s += String.fromCharCode(c);
    i += n;
  }
  return s;
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function b64Encode(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = bytes[i + 1], b2 = bytes[i + 2];
    s += B64[b0 >> 2];
    s += B64[((b0 & 3) << 4) | ((b1 === undefined ? 0 : b1) >> 4)];
    s += b1 === undefined ? '=' : B64[((b1 & 15) << 2) | ((b2 === undefined ? 0 : b2) >> 6)];
    s += b2 === undefined ? '=' : B64[b2 & 63];
  }
  return s;
}

function b64Decode(str) {
  const s = String(str).replace(/[^A-Za-z0-9+/]/g, '');
  const out = [];
  for (let i = 0; i < s.length; i += 4) {
    const n = (B64.indexOf(s[i]) << 18) | (B64.indexOf(s[i + 1]) << 12) |
              ((i + 2 < s.length ? B64.indexOf(s[i + 2]) : 0) << 6) |
              (i + 3 < s.length ? B64.indexOf(s[i + 3]) : 0);
    out.push((n >> 16) & 255);
    if (i + 2 < s.length) out.push((n >> 8) & 255);
    if (i + 3 < s.length) out.push(n & 255);
  }
  return new Uint8Array(out);
}

const b64u  = (bytes) => b64Encode(bytes).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const unb64u = (str) => b64Decode(String(str).replace(/-/g, '+').replace(/_/g, '/'));

function hex(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += (bytes[i] < 16 ? '0' : '') + bytes[i].toString(16);
  return s;
}

/* Comparación en tiempo constante. Un `===` de cadenas se corta en el
   primer carácter distinto, y esa diferencia de tiempo es medible. */
function igualSeguro(a, b) {
  const A = String(a), B = String(b);
  let dif = A.length ^ B.length;
  const n = Math.max(A.length, B.length);
  for (let i = 0; i < n; i++) dif |= (A.charCodeAt(i) || 0) ^ (B.charCodeAt(i) || 0);
  return dif === 0;
}

/* --- contraseñas ---------------------------------------------------- */
/* Formato guardado en personas.hash, todo en una columna:
     pbkdf2$<iteraciones>$<sal en base64url>$<derivado en base64url>     */

const PBKDF2_ITERS = 100000;

function hashClave(clave, salB64u, iters) {
  const it = iters || PBKDF2_ITERS;
  const sal = salB64u ? unb64u(salB64u) : null;
  if (!sal) throw new Error('hashClave: falta la sal');
  return 'pbkdf2$' + it + '$' + b64u(sal) + '$' +
         b64u(pbkdf2Sha256(utf8Bytes(clave), sal, it));
}

function verificaClave(clave, guardado) {
  try {
    const p = String(guardado || '').split('$');
    if (p.length !== 4 || p[0] !== 'pbkdf2') return false;
    const iters = parseInt(p[1], 10);
    if (!(iters > 0 && iters <= 1000000)) return false;
    return igualSeguro(hashClave(clave, p[2], iters), guardado);
  } catch (e) { return false; }
}

/* --- JWT HS256 ------------------------------------------------------ */

function firmaJwt(payload, secreto, segundos) {
  const ahora = Math.floor(Date.now() / 1000);
  const cuerpo = Object.assign({}, payload, { iat: ahora, exp: ahora + segundos });
  const h = b64u(utf8Bytes(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const c = b64u(utf8Bytes(JSON.stringify(cuerpo)));
  const f = b64u(hmacSha256(utf8Bytes(secreto), utf8Bytes(h + '.' + c)));
  return h + '.' + c + '.' + f;
}

/* Devuelve {ok, payload, error}. NUNCA lanza: un token mal formado es un
   dato de entrada, no una falla del programa, y si lanzara, n8n metería
   la ENTRADA del nodo en el payload de error — y la entrada trae el
   secreto. Ver n8n/README.md, regla 2. */
function verificaJwt(token, secreto) {
  try {
    const p = String(token || '').split('.');
    if (p.length !== 3) return { ok: false, error: 'TOKEN_MAL_FORMADO' };

    const cab = JSON.parse(utf8Str(unb64u(p[0])));
    // Sin este candado, un token con alg:"none" pasaría sin firma.
    if (cab.alg !== 'HS256') return { ok: false, error: 'TOKEN_ALG_INVALIDO' };

    const esperada = b64u(hmacSha256(utf8Bytes(secreto), utf8Bytes(p[0] + '.' + p[1])));
    if (!igualSeguro(esperada, p[2])) return { ok: false, error: 'TOKEN_FIRMA_INVALIDA' };

    const cuerpo = JSON.parse(utf8Str(unb64u(p[1])));
    if (!cuerpo.exp || Math.floor(Date.now() / 1000) >= cuerpo.exp) {
      return { ok: false, error: 'TOKEN_VENCIDO' };
    }
    return { ok: true, payload: cuerpo };
  } catch (e) {
    return { ok: false, error: 'TOKEN_ILEGIBLE' };
  }
}

/* =====================================================================
   lib-s3 — URLs firmadas (AWS Signature V4, presigned query string).

   Firmar es puro HMAC: NO hay red de por medio, así que cabe en un nodo
   Code aunque el sandbox no tenga acceso a internet. n8n entrega la URL
   firmada y es el CELULAR quien sube el archivo directo al bucket.
   La foto nunca pasa por n8n ni por la base.

   Depende de lib-cripto (hmacSha256, sha256, utf8Bytes, hex).
   ===================================================================== */

function amzFechas(d) {
  const p = (n, a) => String(n).padStart(a || 2, '0');
  const ymd = d.getUTCFullYear() + p(d.getUTCMonth() + 1) + p(d.getUTCDate());
  return { ymd: ymd, iso: ymd + 'T' + p(d.getUTCHours()) + p(d.getUTCMinutes()) + p(d.getUTCSeconds()) + 'Z' };
}

/* Codificación de URI de AWS: como encodeURIComponent, pero AWS exige
   que ! * ' ( ) también vayan escapados, y que ~ NO lo vaya. Si esto se
   equivoca, la firma no cuadra y el error que devuelve S3 habla de
   credenciales, no de codificación. */
function uriEnc(str, dejarDiagonal) {
  let s = encodeURIComponent(String(str))
    .replace(/[!*'()]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
  if (dejarDiagonal) s = s.replace(/%2F/g, '/');
  return s;
}

function llaveDeFirma(secreto, ymd, region, servicio) {
  let k = hmacSha256(utf8Bytes('AWS4' + secreto), utf8Bytes(ymd));
  k = hmacSha256(k, utf8Bytes(region));
  k = hmacSha256(k, utf8Bytes(servicio));
  return hmacSha256(k, utf8Bytes('aws4_request'));
}

/*
  cfg = { endpoint, region, bucket, keyId, secret, estilo }
    endpoint: 'https://t3.storageapi.dev' (sin diagonal final)
    bucket:   el nombre GLOBAL del bucket, con su hash: la variable
              BUCKET de la pestaña Credentials, no el nombre que se ve
              en el lienzo de Railway
    estilo:   'virtual' (por omisión) o 'path'
  metodo: 'PUT' para subir, 'GET' para ver
  llave:  la ruta dentro del bucket (gastos/12/1789…-ticket.jpg)
  segundos: vigencia
*/
function urlFirmada(cfg, metodo, llave, segundos) {
  const servicio = 's3';
  const ahora = new Date();
  const f = amzFechas(ahora);
  const alcance = f.ymd + '/' + cfg.region + '/' + servicio + '/aws4_request';

  const base = String(cfg.endpoint).replace(/\/+$/, '');
  const hostBase = base.replace(/^https?:\/\//, '').split('/')[0];
  const esquema = base.startsWith('http://') ? 'http://' : 'https://';

  /* DOS estilos de URL, y elegir mal NO da un error que hable de esto:
     da un fallo de firma, porque el host y la ruta entran en el texto
     que se firma.

       virtual-hosted   https://<bucket>.<endpoint>/<llave>   <- Railway
       path             https://<endpoint>/<bucket>/<llave>   <- buckets viejos

     Railway dice: "Railway Buckets use virtual-hosted-style URLs, where
     the bucket name appears as the subdomain of the S3 endpoint", y que
     los buckets creados antes de ese cambio pueden necesitar path —
     la pestaña Credentials del bucket dice cuál toca. Por eso es un
     ajuste (config_app.s3_estilo) y no una decisión escrita aquí. */
  const path = String(cfg.estilo || '').toLowerCase() === 'path';
  const host = path ? hostBase : uriEnc(cfg.bucket) + '.' + hostBase;
  const ruta = (path ? '/' + uriEnc(cfg.bucket) : '') + '/' + uriEnc(llave, true);

  const q = [
    ['X-Amz-Algorithm', 'AWS4-HMAC-SHA256'],
    ['X-Amz-Credential', cfg.keyId + '/' + alcance],
    ['X-Amz-Date', f.iso],
    ['X-Amz-Expires', String(segundos)],
    ['X-Amz-SignedHeaders', 'host']
  ];
  // AWS exige los parámetros ordenados por nombre codificado.
  const consulta = q.map((kv) => [uriEnc(kv[0]), uriEnc(kv[1])])
                    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
                    .map((kv) => kv[0] + '=' + kv[1])
                    .join('&');

  const pedidoCanonico = [
    metodo, ruta, consulta,
    'host:' + host, '',      // cabeceras canónicas + línea en blanco
    'host',                  // cabeceras firmadas
    'UNSIGNED-PAYLOAD'
  ].join('\n');

  const porFirmar = [
    'AWS4-HMAC-SHA256', f.iso, alcance,
    hex(sha256(utf8Bytes(pedidoCanonico)))
  ].join('\n');

  const firma = hex(hmacSha256(llaveDeFirma(cfg.secret, f.ymd, cfg.region, servicio), utf8Bytes(porFirmar)));
  return esquema + host + ruta + '?' + consulta + '&X-Amz-Signature=' + firma;
}

/* La llave del ticket la arma el SERVIDOR, nunca el navegador: si el
   cliente propusiera la ruta, podría pedir una URL firmada para
   sobrescribir el ticket de otro evento. Va con marca de tiempo para
   que cambiar la foto no pise la anterior. */
function llaveTicket(gastoId, nombreArchivo) {
  const ext = (String(nombreArchivo || '').match(/\.([A-Za-z0-9]{1,5})$/) || [, 'jpg'])[1].toLowerCase();
  const limpio = ext.replace(/[^a-z0-9]/g, '') || 'jpg';
  return 'gastos/' + gastoId + '/' + Date.now() + '.' + limpio;
}


const MIN_SUBIR = 10 * 60;   // 10 min para subir desde el celular
const MIN_VER   = 5 * 60;    // 5 min para ver, como se pidió

let salida;
try {
  const arm = $('Code - Armar consulta').first().json || {};

  if (!arm.ok) {
    salida = { ok: false, error: arm.error || 'NO_AUTORIZADO' };
  } else if (!arm.firmar) {
    // Esta acción no pedía firma: es una mutación normal y se responde
    // igual que en los otros workflows. Cero renglones tocados con
    // sesión válida = el WHERE excluyó el renglón.
    const fila = $input.first().json || {};
    const n = Number(fila.afectadas || 0);
    salida = n > 0
      ? { ok: true, afectadas: n, id: fila.id === undefined ? null : String(fila.id) }
      : { ok: false, error: 'NO_PERMITIDO_O_NO_EXISTE' };
  } else {
    const fila = $input.first().json;

    if (!fila || !fila.gasto_id) {
      // Cero renglones = el WHERE excluyó el gasto. Ni existe para esta
      // sesión, ni se le dice cuál de las dos cosas es.
      salida = { ok: false, error: 'NO_PERMITIDO_O_NO_EXISTE' };
    } else if (!fila.s3_endpoint || !fila.s3_key_id || !fila.s3_secret) {
      salida = { ok: false, error: 'CONFIG_SIN_BUCKET' };
    } else {
      const cfg = {
        endpoint: fila.s3_endpoint, region: fila.s3_region || 'us-east-1',
        bucket: fila.s3_bucket, keyId: fila.s3_key_id, secret: fila.s3_secret,
        estilo: fila.s3_estilo || 'virtual'
      };

      if (arm.firmar === 'PUT') {
        // La ruta la arma el SERVIDOR. Si la propusiera el cliente,
        // podría pedir una URL firmada apuntando al ticket de otro
        // evento y sobrescribirlo.
        const llave = llaveTicket(fila.gasto_id, arm.nombre_archivo);
        salida = { ok: true, modo: 'subir', ticket_key: llave,
                   url: urlFirmada(cfg, 'PUT', llave, MIN_SUBIR), vence_en: MIN_SUBIR };
      } else if (!fila.ticket_key) {
        salida = { ok: false, error: 'SIN_TICKET' };
      } else {
        salida = { ok: true, modo: 'ver', ticket_key: fila.ticket_key,
                   url: urlFirmada(cfg, 'GET', fila.ticket_key, MIN_VER), vence_en: MIN_VER };
      }
    }
  }
} catch (e) {
  salida = { ok: false, error: 'FIRMA_FALLO' };
}

return [{ json: salida }];
